(* [comment removed for export] *)
Definition kblk (kel arr h : Z) (rows : Z -> Z) (q : word) : Prop :=
  q = Z_to_bv 64 kel \/ q = Z_to_bv 64 arr \/ exists i, (0 <= i < h)%Z /\ q = Z_to_bv 64 (rows i).

Lemma kern_sub_live : forall C A A' m kel arr h w rows, kern C A A' m kel arr h w rows -> sub_live A A'.
Proof.
